class Inventory:
    def __init__(self):
        self._items: dict[str, dict] = {}

    def add_item(self, name: str, quantity: int, price: float) -> None:
        if name in self._items:
            self._items[name]['quantity'] -= quantity  # bug: should be +=
        else:
            self._items[name] = {'quantity': quantity, 'price': price}

    def remove_item(self, name: str, quantity: int) -> None:
        if name not in self._items:
            raise KeyError(f'{name} not in inventory')
        # bug: allows negative stock, should raise if quantity > current
        self._items[name]['quantity'] -= quantity

    def total_value(self) -> float:
        # bug: multiplies quantity by quantity instead of price
        return sum(v['quantity'] * v['quantity'] for v in self._items.values())

    def stock(self, name: str) -> int:
        return self._items[name]['quantity']
